class Solution {
  public Node lowestCommonAncestor(Node p, Node q) {
    // each pointer walks up, then restarts from the other node, so both cover depth(p) + depth(q)
    Node a = p, b = q;
    while (a != b) {
      a = a == null ? q : a.parent;
      b = b == null ? p : b.parent;
    }
    return a;
  }
}
